    hebrewTranslation: `וממקור אחר נאמר: מן הצבעים שייך לה האדום; מן המתכות — הברזל. היא מורה על אנדרוגינוס, על שפחות, על אנשי פריצות, על ילדים שנעשה בהם מעשה אסור, ועל אשה זונה — לפי העדים, כאשר נשאלים על כך. היא מורה גם על סרסורים וסרסוריות, על עורמה, בגידה ורכילות; על ברזל מעובד כגון כלי נשק ודומיהם; ועל שמחה ורע, מפני שהיא ממוזגת. היא משובחת במה שמבקשים להוציא, ומגונה במה שמבקשים להכניס. היא מורה על כתיבה לילד קטן, על קמיע או חפץ טמון, על קבורת חולה, ובנישואין היא טובה.

ומן הנאמר עליה בשיר:

בשורה לך במזל הטוב הנכבד של נלחם, אתה שבאת לבקש ביאור השאלה.
כל צורה מן השמחה מודיעה לך על חתונות ועל שמחות.
ולחולה — דון בה למוות אם תיראה בראש הבתים.
אם תיראה עם המזיקים — תכונותיה כחרבות הודו שנשלפו ביום מלחמה.
אם אין העדים מעידים במיטיבם — היזהר בה בכל היתדות.
וריבוי חזרתה מצדדים שונים — יש לחשוש בו לחלש מן צעקה.
אם אינו כבול בברזל, חוששים לאסיר מאיום.
ולנוסע היא שמחה גדולה, ולמעוברת היא מבשרת זכרים.`,
