    chapterHebrew: `הוצאת הדמיר — המשך — תועלת מהזנאתי: האִמְתִזַאג׳ (ערבול-הצורות) וזוגות-הצורות`,
    hebrewTranslation: `תועלת גדולה מדברי אל־זנאתי
מיזוג הצורות
דע כי כאשר עורכים מערך לשם גילוי הכוונה הנסתרת, הצורות מתעצבות לפי צורת הכוונה הנסתרת. שקול זאת בדעתך והתבונן.

תועלת גדולה מדברי האستاذ הגדול אל־זנאתי: הוא חילק את שישה־עשר הבתים לשמונה זוגות, וכל שתי צורות עשה להן מזג אחד. כל צורה מבקשת צורה אחת אחרת, והיא המבוקשת שלה.

לדוגמה: אם נשוא ראש נשוא ראש [] עומד בראשון — התבונן בסף נכנס סף נכנס []. ואם סף נכנס עומד בראשון — התבונן בנשוא ראש. שם עשויה להתגלות מחשבת השואל.

דרך המיזוג נעשית לפי הנקודה והפחתתה שמונה שמונה. והיא נקראת מיזוג היסודות, על חשבון אבג׳ד: אל״ף באחד, בי״ת בשניים, גימ״ל בשלושה ודל״ת בארבעה. לאחר שמחשבים את נקודות הצורה, מפחיתים שמונה שמונה; וכל צורה שמתאימה למספר אותיות אבג׳ד — שם מקומה במיזוג.`,
    topics: ["זנאתי","שיטת-אמתזאג׳","שישה-עשר-בתים-לשמונה-זוגות","מזג-משותף","כל-צורה-מבקשת-מזוגה","אחיאן-עתבה-דחולה-זוג","השלך-8","אמתזאג-ענאסר","חשבון-אבגד","אלף-1-באא-2-גים-3-דאל-4","ספור-נקודות-השלך-8","אות-לצורה"],
    sourceStatus: "explicit-in-source",
