    chapter: `أحكام الأشكال — فصل فوارس العلم (الشواهد السبعة) — فصل مولاة الأشكال ومقارنتها`,
    chapterHebrew: `דיני הצורות — פסקה שבעת-השהאדים — פסקה מוּלָאאַת הצורות (חיבורים)`,
    hebrewTranslation: `דיני מקצת הצורות
ושבעת עדי החכמה
בר הלחי בר הלחי [] — רצונותיו רבים, תקוותיו מתארכות, ותועלתו מועטה. סף נכנס סף נכנס [] מורה על ריבוי תועלת. נשוא ראש נשוא ראש [], קוסג׳ וכבוד יוצא כבוד יוצא [] — תפיסתם מועטה וטורחם מרובה; ואין נותנים את התאוות אלא כשהם בבתים מיטיבים. ואם הם בבתים מזיקים — אין מתקבל דבר כלל.

פרק: פרשי החכמה הזאת
עדי החכמה הם שבעה: התשיעי, העשירי, האחד־עשר, השנים־עשר, השלושה־עשר, הארבעה־עשר והחמישה־עשר. והשישה־עשר נוסף כדי לדעת בו את הכוונה הנסתרת של השואל.

כאשר רבות במאזנים האלה צורות מיטיבות — שפוט על פיהן. וכן אם גוברות בהן צורות מזיקות — שפוט על פיהן. ואם הצורה מן הקבועות והיא פנימית, הדבר מתקבל אך מתאחר.

פרק: קִרבת הצורות והשוואתן
אם צורת מאדים קרבה לצורת נוגה, היא מורה על פריצות. אם אדום קרבה לצורה משובחת, היא מורה על זהב ועל לבושים אדומים; ואם היא צורה מזיקה, היא מורה על הריגה ודם, והאבדה אינה חוזרת.`,
    topics: ["מהירות-צורות","נקי-הח׳ד-מהיר","עתבה-דאח׳לה-מהירה","אחיאן-כוסג-נצרה-חרוג-אחיזה-מעטה","שבעת-שהאדים","בתים-9-15-שהאדים","בית-16-דמיר-שואל","ת׳ואבת-דאח׳ל-יתאחר","מולאאת-הצורות","שכל-מריח-זהרה-פריצות","חמרה-מחמוד-זהב","חמרה-נחס-הרג","נקי-ביאד-שחרור","ביאד-נקבית-בהיריון","אנכיס-מגנה-אישה-גנאית","אחיאן-חולה","אחיאן-בית-10-מנהיג","נצרה-דאח׳לה-ת׳קאף-אישה","נצרה-חרוג׳ה-חמרה-מתכת"],
