    topics: ["טבלת-טמטם-עומק-מים","אחיאן-ביאץ-נצרה-ח׳ארגה=7-אמות-12-רוחב","נצרה-דאח׳לה-נקי-אלח׳ד=7-אמות","ג׳ודלה-קבץ-דאח׳ל-קבץ-ח׳ארג=אחת","גמאעה=16-אמות","עקלה-אגתמאע-טריק=4-אמות-6-רוחב","קרוב-או-רחוק","קמר=קרוב","עטארד-מושתרי=קרוב-אבל-קשה","זחל=דרך-קוצנית","הוואאי=צפון","נארי=מזרח","טוראבי=קיבלה","מאאי=מערב","ח׳בייה-בבית","חלק-4-כיוונים","ריקות=אין-מלאות=שם","ממשיך"],
