    topics: ["תוצאת-כפל","סוואקט=יתרפא-מהר","מאוואאיל=חולשה-תתארך","אוותאד=מחלה-עד-מוות","תסכין-אעצאא","טבלת-איברים-גוף","ראס=גמאעה+אגתמאע","רקבה=ביאץ","צדר=נקי-אלח׳ד","בטן=טריק+נצרה-ח׳ארגה","דובור=חמרה","קובול=נצרה-דאח׳לה","יד-ימין=עקלה","כתף=קבץ-ח׳ארג","גנב=אנכיס","פח׳ד=ג׳ודלה","רג׳ל=תשמיר","כתף-שמאל=קבץ-דאח׳ל","גנב-שמאל=עתבה-ח׳ארגה","פח׳ד-שמאל=עתבה-דאח׳לה","רגל-שמאל=ראיית-אלפרח","הוואא-אלהוואא","נשמת-חולה","סוואקט=תקווה","אוותאד=תקווה","מאוואאיל=תתארך","ממשיך"],
