    chapter: `الفصل الثامن: سرقة البهائم — تتمة (صفة الجمال والحمير والغنم والطيور)؛ رجوع الخيل والجمال والحمير؛ ملح الرمل: أماكن البيوت (الأحيان والبياض في الأركان)`,
    chapterHebrew: `פרק שמיני: גנבת בהמות — המשך (גמלים, חמורים, צאן, עופות); חזרת סוסים/גמלים וחמורים; מלח הראמל: מיקומי בתים (אחיאן ובּיאד בפינות)`,
    hebrewTranslation: `גניבת בהמות
וחזרת סוסים, גמלים וחמורים
— ומן השנים־עשר צורה. אם יצאה כצורות מסוימות, היא תיאור הגמלים, הבהמות הגדולות והמקנה הגדול; ואם יצאה כצורות אחרות, היא תיאור החמורים; ואם יצאה כצורות אחרות, היא תיאור הצאן; ואם יצאה כצורות אחרות, היא תיאור העופות. דין זה תלוי בצורות שיצאו ובעדותן.

לדעת אם סוסים וגמלים ישובו: הכה את הראשון עם השנים־עשר והוצא מהם צורה. קח גם מן הרביעי והשנים־עשר צורה, והוצא מהם צורה נוספת. אם יצאה צורה פנימית, דון לחזרה; ואם יצאה חיצונית, לא ישובו.

ואם האובדן הוא מצד חמורים או צאן, קח מן הראשון והשישי צורה, ומן הרביעי והשישי צורה, ומהשתיים הוצא צורה שלישית. דון בה כדרך הדין הראשון.

ממליחות חכמת גורל החול — מקומות הבתים: אם רצית לדעת מקומות בתים, התבונן בבית הראשון, החמישי, העשירי והשנים־עשר. חפש בהם נשוא ראש, לבן, חיבור ואדום. אם ראית אחת מן הצורות האלה בבתים האלה, אמור: סמוך לבית הנשאל יש מסגד או בית לימוד. ודע כי הראשון—`,
    topics: ["גנבת-בהמות-ב6+12=זיהוי-סוג","צורות-גדולות=גמלים-בהמות","בינוניות=חמורים","סוג-א=צאן","סוג-ב=עופות","חזרת-סוסים-גמלים-ב1×12+ב4×12","דאח׳ל=יחזרו","ח׳ארג=לא-יחזרו","חמורים-צאן-ב1×6+ב4×6","מלח-ראמל-מיקומי-בתים","ב1-5-10-12-אחיאן-בּיאד-אג׳תמאע-חֻמְרָה=מסגד-קרוב","ב1+5=ליד-שואל","ב10+12=ליד-מסאול"],
