    chapterHebrew: `מחוץ-לספר (המשך): פחד ב7+ב8; ⚠️ נזהת-עקול: האסיר לפי צורות`,
    hebrewTranslation: `האסיר — אורך המאסר, סכנה ושחרור
אם הבית השישה־עשר והבית השנים־עשר שניהם מזיקים ויוצאים — ישלים האסיר זמן רב במאסרו. ואם שניהם מזיקים ונכנסים, והצורות המזיקות מעידות להן, ורבתה צורת אדום (אל־חֻמְרַה / الحمرة) במערך גורל החול — הדבר עלול להגיע לשפיכות דמים. ואם שניהם מזיקים ונכנסים, הוא חולה ומת.

ויש שאמרו: בפדיון שבוי, הולד צורה מן הראשון ומן השלושה־עשר. אם היא יוצאת — הוא נחלץ; ואם היא נכנסת — הדבר מתאחר. והפחד נידון מן השביעי והשמיני: אם הדין מיטיב — הפחד בטל; ואם הוא מזיק — הפחד עומד במקומו.

מתוספת נֻזְהַת אל־עֻקוּל
בשאלת אסיר: הוצא צורה מן הראשון ומן החמישי, ודון לפי אותה צורה. אם היא יוצאת — דון ביציאה מן המאסר; ואם היא נכנסת — דון בעיכוב ובשהייה.

בדיני אסירים: אם יצאו שתי הצורות נלחם (אל־ג׳וּדְלַה / الجودلة) ו־בר הלחי (נַקִי אל־חַ׳ד / نقي الخد) — הוא מת במאסרו. אם יצאו ממון יוצא (אל־קַבְּד׳ אל־חַ׳ארִג׳ / القبض الخارج), ממון נכנס (אל־קַבְּד׳ א־דַאחִ׳ל / القبض الداخل) ו־אדום (אל־חֻמְרַה / الحمرة) — מגיע עליו עונש בתוך מאסרו.

אם יצאו דרך (א־טַרִיק / الطريق), סף יוצא (אל־עַתַבַּה אל־חַ׳ארִגַ׳ה / العتبة الخارجة) ו־סף נכנס (אל־עַתַבַּה א־דַאחִ׳לַה / العتبة الداخلة) — יארך מאסרו זמן רב, אך אחר כך ישוחרר בהשתדלות אדם אחר. אם יצאו קהלה (אל־ג׳ַמַאעַה / الجماعة) ו־לבן (אל־בַּיַאד׳ / البياض) — תבוא עליו מחלה במאסרו, אך אפשר שיבריא ויינצל. ואם יצאה חיבור (אל־אִג׳ְתִמַאע / الاجتماع) — יש לחשוש שנכשל בעבירה שהוא נענש עליה, ואחר כך ישוחרר. ואם יצאו כבוד נכנס (א־נֻצְרַה א־דַאחִ׳לַה / النصرة الداخلة) ו־כבוד יוצא (א־נֻצְרַה אל־חַ׳ארִגַ׳ה / النصرة الخارجة) — ישלם קנס וישוחרר.`,
